-- Initial schema; no content or license grants are seeded.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE editorial_status AS ENUM ('draft','in_review','approved','published','archived');
CREATE TYPE access_level AS ENUM ('free','premium');
CREATE TYPE subscription_status AS ENUM ('pending','active','grace','past_due','canceled','expired','refunded');
CREATE TYPE profile_role AS ENUM ('reader','editor','admin');
CREATE TABLE profiles (id uuid PRIMARY KEY, display_name text, role profile_role NOT NULL DEFAULT 'reader', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE licenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), holder text NOT NULL, evidence_url text NOT NULL, permissions text NOT NULL, restrictions text, valid_from timestamptz, valid_until timestamptz, verified_at timestamptz, verified_by uuid REFERENCES profiles(id), notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE translations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, language text NOT NULL, canon text NOT NULL, license_id uuid REFERENCES licenses(id), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')), attribution text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE books (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), translation_id uuid NOT NULL REFERENCES translations(id), code text NOT NULL, slug text NOT NULL, name text NOT NULL, order_no integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(translation_id,code));
CREATE TABLE chapters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books(id), number integer NOT NULL CHECK (number > 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(book_id,number));
CREATE TABLE verses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chapter_id uuid NOT NULL REFERENCES chapters(id), number integer NOT NULL CHECK (number > 0), content text NOT NULL, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(chapter_id,number));
-- Approval must be checked when publishing verses and when changing translation status.
CREATE FUNCTION enforce_verse_license() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.published AND NOT EXISTS (SELECT 1 FROM chapters c JOIN books b ON b.id=c.book_id JOIN translations t ON t.id=b.translation_id JOIN licenses l ON l.id=t.license_id WHERE c.id=NEW.chapter_id AND t.status='approved' AND l.verified_at IS NOT NULL AND (l.valid_from IS NULL OR l.valid_from <= now()) AND (l.valid_until IS NULL OR l.valid_until > now())) THEN RAISE EXCEPTION 'published verse requires approved, verified and current license'; END IF; RETURN NEW; END $$;
CREATE TRIGGER verse_license BEFORE INSERT OR UPDATE ON verses FOR EACH ROW EXECUTE FUNCTION enforce_verse_license();
CREATE FUNCTION protect_translation_license() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF EXISTS (SELECT 1 FROM books b JOIN chapters c ON c.book_id=b.id JOIN verses v ON v.chapter_id=c.id WHERE b.translation_id=NEW.id AND v.published) AND (NEW.status <> 'approved' OR NEW.license_id IS DISTINCT FROM OLD.license_id) THEN RAISE EXCEPTION 'unpublish verses before changing translation approval or license'; END IF; RETURN NEW; END $$;
CREATE TRIGGER translation_license BEFORE UPDATE ON translations FOR EACH ROW EXECUTE FUNCTION protect_translation_license();
CREATE TABLE studies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, summary text NOT NULL, type text NOT NULL, level text NOT NULL, status editorial_status NOT NULL DEFAULT 'draft', access access_level NOT NULL DEFAULT 'free', published_version_id uuid, reviewer_id uuid REFERENCES profiles(id), published_at timestamptz, created_by uuid REFERENCES profiles(id), updated_by uuid REFERENCES profiles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE study_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), study_id uuid NOT NULL REFERENCES studies(id), version integer NOT NULL CHECK (version > 0), changelog text NOT NULL, author_id uuid NOT NULL REFERENCES profiles(id), reviewer_id uuid REFERENCES profiles(id), status editorial_status NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(study_id,version), UNIQUE(study_id,id));
ALTER TABLE studies ADD CONSTRAINT published_version_belongs_to_study FOREIGN KEY (id,published_version_id) REFERENCES study_versions(study_id,id);
CREATE TABLE study_sections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid NOT NULL REFERENCES study_versions(id), title text NOT NULL, order_no integer NOT NULL, content text NOT NULL, visibility access_level NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(version_id,order_no));
CREATE INDEX study_sections_public_idx ON study_sections(version_id,visibility,order_no);
CREATE TABLE sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work text NOT NULL, author text NOT NULL, publisher text, edition text, year integer, identifier text, license_id uuid REFERENCES licenses(id), editorial_reliability text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE source_locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES sources(id), locator text NOT NULL, permitted_excerpt text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE source_claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid NOT NULL REFERENCES study_versions(id), claim text NOT NULL, source_location_id uuid REFERENCES source_locations(id), kind text NOT NULL CHECK (kind IN ('quote','paraphrase','editorial_synthesis')), verification_note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (kind='editorial_synthesis' OR source_location_id IS NOT NULL));
CREATE TABLE topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, description text NOT NULL, status editorial_status NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE authors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE works (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, license_id uuid REFERENCES licenses(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE traditions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE debates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE study_passages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), study_id uuid NOT NULL REFERENCES studies(id), reference text NOT NULL, relation_type text NOT NULL, confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1), editorial_note text NOT NULL, version_id uuid NOT NULL REFERENCES study_versions(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE study_topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), study_id uuid NOT NULL REFERENCES studies(id), topic_id uuid NOT NULL REFERENCES topics(id), relation_type text NOT NULL, confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1), editorial_note text NOT NULL, version_id uuid NOT NULL REFERENCES study_versions(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE study_authors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), study_id uuid NOT NULL REFERENCES studies(id), author_id uuid NOT NULL REFERENCES authors(id), relation_type text NOT NULL, confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1), editorial_note text NOT NULL, version_id uuid NOT NULL REFERENCES study_versions(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE work_authors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_id uuid NOT NULL REFERENCES works(id), author_id uuid NOT NULL REFERENCES authors(id), relation_type text NOT NULL, confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1), editorial_note text NOT NULL, version_id uuid NOT NULL REFERENCES study_versions(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE work_topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_id uuid NOT NULL REFERENCES works(id), topic_id uuid NOT NULL REFERENCES topics(id), relation_type text NOT NULL, confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1), editorial_note text NOT NULL, version_id uuid NOT NULL REFERENCES study_versions(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE debate_topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), debate_id uuid NOT NULL REFERENCES debates(id), topic_id uuid NOT NULL REFERENCES topics(id), relation_type text NOT NULL, confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1), editorial_note text NOT NULL, version_id uuid NOT NULL REFERENCES study_versions(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE debate_traditions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), debate_id uuid NOT NULL REFERENCES debates(id), tradition_id uuid NOT NULL REFERENCES traditions(id), relation_type text NOT NULL, confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1), editorial_note text NOT NULL, version_id uuid NOT NULL REFERENCES study_versions(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL, version integer NOT NULL, price_minor integer NOT NULL CHECK(price_minor >= 0), currency text NOT NULL, period text NOT NULL, features jsonb NOT NULL, status text NOT NULL, renewal_text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(key,version));
CREATE TABLE subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES profiles(id), plan_id uuid NOT NULL REFERENCES plans(id), status subscription_status NOT NULL DEFAULT 'pending', provider text NOT NULL, external_id text, current_period_end timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,external_id));
CREATE TABLE payment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, external_event_id text NOT NULL, type text NOT NULL, subscription_id uuid REFERENCES subscriptions(id), minimized_payload jsonb NOT NULL DEFAULT '{}', received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, result text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,external_event_id));
CREATE TABLE entitlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES profiles(id), feature text NOT NULL, resource_id uuid, source_subscription_id uuid REFERENCES subscriptions(id), starts_at timestamptz NOT NULL, ends_at timestamptz, state text NOT NULL CHECK(state IN ('active','revoked')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at IS NULL OR ends_at > starts_at));
CREATE INDEX entitlements_access_idx ON entitlements(user_id,feature,state);
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES profiles(id), action text NOT NULL, resource_type text NOT NULL, resource_id uuid, result text NOT NULL, minimized_metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
